const coreDeck=document.createElement('section');coreDeck.className='core-deck';coreDeck.setAttribute('aria-label','PatchWarden orchestration core and fleet health');
coreDeck.innerHTML=`<div class="core-stage"><canvas id="core-canvas" aria-hidden="true"></canvas><div class="core-kicker"><span class="dot"></span> ORCHESTRATION ENGINE</div><div class="core-mode">● SYSTEM ONLINE</div><div class="core-center"><div class="core-glyph">${icon('shield')}</div><strong>WARDEN</strong><small>FLEET CONTROL CORE</small></div><button class="core-node risk" data-detail="0">production-api<span>18 critical patches</span></button><button class="core-node" data-detail="3">staging-web<span>Rollout in progress</span></button><button class="core-node" data-detail="7">production-web<span>320 assets protected</span></button><button class="core-node" data-detail="4">internal-services<span>Rollout in progress</span></button><div class="core-caption"><span>12 GROUPS · 1,248 CONNECTED ASSETS</span><button id="core-motion" aria-pressed="false">Ⅱ Pause motion</button></div></div><div class="core-readout"><div class="readout-kicker">FLEET COMPLIANCE</div><div class="core-score"><strong id="core-percent">67%</strong><span>compliant</span></div><div class="health-meter" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i data-meter="${i}"></i>`).join('')}</div><div class="core-stat"><span>Protected assets</span><strong id="core-protected">834 / 1,248</strong></div><div class="core-stat"><span>Critical patches</span><strong class="crimson" id="core-critical">42 unresolved</strong></div><div class="core-stat"><span>Active deployments</span><strong id="core-running">02 running</strong></div><div class="readout-footer"><span class="core-wave" aria-hidden="true">${[5,11,17,8,14,6,12,18,9].map((h,i)=>`<i style="--h:${h}px;--d:${i*.1}s"></i>`).join('')}</span> DEMO TELEMETRY · LIVE</div></div>`;
$('.summary').before(coreDeck);
views.overview[0]='Fleet command center';views.overview[1]='Every asset. Every patch. One connected system.';if(view==='overview'){$('#title').textContent=views.overview[0];$('#subtitle').textContent=views.overview[1];$('#breadcrumb').textContent=views.overview[0]}
const priorCoreRender=render;function syncCore(){coreDeck.hidden=!['overview','deployments'].includes(view);const protectedAssets=data.filter(a=>a.status==='compliant').reduce((sum,a)=>sum+a.assets,0);const percentage=Math.round(protectedAssets/1248*100);$('#core-percent').textContent=percentage+'%';$('#core-protected').textContent=protectedAssets.toLocaleString()+' / 1,248';$('#core-critical').textContent=data.reduce((sum,a)=>sum+a.missing,0)+' unresolved';$('#core-running').textContent=String(data.filter(a=>a.status==='deploying').length).padStart(2,'0')+' running';document.querySelectorAll('[data-meter]').forEach((e,i)=>e.classList.toggle('on',i<Math.round(percentage/100*24)));coreDeck.querySelectorAll('[data-detail]').forEach(e=>{const a=data[Number(e.dataset.detail)];e.classList.toggle('risk',a.status==='critical');e.querySelector('span').textContent=a.status==='critical'?a.missing+' critical patches':a.status==='deploying'?'Rollout in progress':a.status==='reboot'?'Awaiting reboot':a.assets+' assets protected'})}render=function(){priorCoreRender();syncCore()};syncCore();
const canvas=$('#core-canvas'),ctx=canvas.getContext('2d');let cw=0,ch=0,coreTime=0,previousFrame=0,motionPaused=false,inViewport=true,raf=0;const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
new ResizeObserver(entries=>{const rect=entries[0].contentRect;cw=rect.width;ch=rect.height;const dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(cw*dpr);canvas.height=Math.round(ch*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);drawCore()}).observe(canvas.parentElement);
new IntersectionObserver(entries=>{inViewport=entries[0].isIntersecting;if(inViewport)startCore()}).observe(canvas);
function coreLine(x1,y1,x2,y2,color,width=1){ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x2,y2);ctx.strokeStyle=color;ctx.lineWidth=width;ctx.stroke()}
function drawCore(){if(!cw||!ch)return;ctx.clearRect(0,0,cw,ch);const x=cw*.5,y=ch*.48,r=Math.min(cw*.205,ch*.31),t=coreTime;const aura=ctx.createRadialGradient(x,y,r*.3,x,y,r*1.75);aura.addColorStop(0,'#b8ffd41c');aura.addColorStop(.48,'#65bd8c15');aura.addColorStop(1,'#75d69c00');ctx.fillStyle=aura;ctx.fillRect(0,0,cw,ch);
// A layered, rotating data sphere surrounding the orchestration core.
for(let j=0;j<4;j++){ctx.save();ctx.translate(x,y);ctx.rotate(t*.11+j*Math.PI/4);ctx.beginPath();ctx.ellipse(0,0,r*1.43,r*(.32+j*.035),0,0,Math.PI*2);ctx.strokeStyle=j===0?'#a1dbb450':'#8cc8ad22';ctx.lineWidth=.7;ctx.stroke();ctx.restore()}
for(let i=0;i<96;i++){const angle=i/96*Math.PI*2;const outer=i%8===0?r*1.35:r*1.3;coreLine(x+Math.cos(angle)*r*1.25,y+Math.sin(angle)*r*1.25,x+Math.cos(angle)*outer,y+Math.sin(angle)*outer,i%8===0?'#b3ebc67a':'#9ecfaf30',i%8===0?1.5:1)}
for(let k=0;k<3;k++){ctx.beginPath();ctx.arc(x,y,r*(.82+k*.15),t*(k%2?-.16:.12)+k*2.1,t*(k%2?-.16:.12)+k*2.1+Math.PI*1.14);ctx.strokeStyle=k===0?'#c1f6d6b0':'#9fdbbd48';ctx.lineWidth=k===0?1.6:.7;ctx.stroke()}
const points=[];for(let i=0;i<160;i++){const v=1-2*(i+.5)/160;const radius=Math.sqrt(1-v*v);const angle=i*2.399963+t*.13;let px=Math.cos(angle)*radius,py=v,pz=Math.sin(angle)*radius;const ry=py*Math.cos(.3)-pz*Math.sin(.3),rz=py*Math.sin(.3)+pz*Math.cos(.3);points.push({x:x+px*r*1.13,y:y+ry*r*1.13,z:rz})}points.sort((a,b)=>a.z-b.z);points.forEach((p,i)=>{if(Math.hypot(p.x-x,p.y-y)<r*.73)return;ctx.beginPath();ctx.arc(p.x,p.y,p.z>0?1.4:.7,0,Math.PI*2);ctx.fillStyle=`rgba(170,232,195,${.18+(p.z+1)*.3})`;ctx.fill();if(i%5===0&&points[i+1])coreLine(p.x,p.y,points[i+1].x,points[i+1].y,'#86c4a215',.5)});
const fill=ctx.createRadialGradient(x-r*.2,y-r*.35,2,x,y,r*.77);fill.addColorStop(0,'#426854');fill.addColorStop(.6,'#213f36');fill.addColorStop(1,'#152e2a');ctx.beginPath();ctx.arc(x,y,r*.75,0,Math.PI*2);ctx.fillStyle=fill;ctx.fill();ctx.strokeStyle='#a6dfb86b';ctx.lineWidth=1;ctx.stroke();ctx.beginPath();ctx.arc(x,y,r*.68,0,Math.PI*2);ctx.strokeStyle='#93d5ad24';ctx.stroke();
const nodes=[{x:cw*.18,y:ch*.35,id:0},{x:cw*.82,y:ch*.36,id:3},{x:cw*.2,y:ch*.72,id:7},{x:cw*.8,y:ch*.72,id:4}];nodes.forEach((n,i)=>{const angle=Math.atan2(n.y-y,n.x-x),sx=x+Math.cos(angle)*r*1.28,sy=y+Math.sin(angle)*r*1.28;const critical=data[n.id].status==='critical';const c=critical?'#e8919d':'#b2eccc';coreLine(sx,sy,n.x,n.y,critical?'#b8758145':'#8bc3a54a',.8);for(let k=0;k<3;k++){const f=(t*.15+i*.27+k/3)%1;const dx=sx+(n.x-sx)*f,dy=sy+(n.y-sy)*f;ctx.beginPath();ctx.arc(dx,dy,1.8,0,Math.PI*2);ctx.fillStyle=c;ctx.fill()}ctx.beginPath();ctx.arc(sx,sy,3,0,Math.PI*2);ctx.fillStyle=c;ctx.fill()});
if(document.body.classList.contains('scan-active')){const rr=r*(.8+(t%1.5));ctx.beginPath();ctx.arc(x,y,rr,0,Math.PI*2);ctx.strokeStyle='#baf9d777';ctx.lineWidth=2;ctx.stroke()}}
function animateCore(now){raf=0;if(document.hidden||!inViewport||motionPaused||reducedMotion.matches||coreDeck.hidden){previousFrame=0;return}if(previousFrame)coreTime+=Math.min((now-previousFrame)/1000,.05);previousFrame=now;drawCore();raf=requestAnimationFrame(animateCore)}function startCore(){if(!raf&&!motionPaused&&!reducedMotion.matches){previousFrame=0;raf=requestAnimationFrame(animateCore)}else drawCore()}
$('#core-motion').onclick=()=>{motionPaused=!motionPaused;coreDeck.classList.toggle('core-paused',motionPaused);$('#core-motion').textContent=motionPaused?'▶ Resume motion':'Ⅱ Pause motion';$('#core-motion').setAttribute('aria-pressed',String(motionPaused));startCore()};document.addEventListener('visibilitychange',startCore);window.addEventListener('hashchange',startCore);reducedMotion.addEventListener('change',startCore);startCore();
